SELECT p.id AS position_id, s.interval_code, s.decision AS ref_decision, a.id, a.reference_signal_id, a.evaluation_path, a.evaluated_at, a.created_at, a.one_hour_signal_id, a.one_hour_raw_decision, a.one_hour_effective_decision, a.one_hour_age_seconds, a.five_minute_signal_id, a.five_minute_raw_decision, a.assessment_band, a.max_initial_percent, a.final_result, LEFT(a.final_reason,400) AS final_reason FROM paper_position p JOIN trade_signal s ON s.symbol = p.symbol AND s.generated_at BETWEEN p.opened_at - INTERVAL 10 MINUTE AND p.opened_at JOIN buy_htf_assessment_audit a ON a.reference_signal_id = s.id WHERE p.id IN (104,101,96,91,82,78) ORDER BY p.id, a.id